@Override
public String store(MultipartFile file) {
    if (file == null || file.isEmpty()) {
        return null;
    }

    if (file.getSize() > maxFileSize) {
        throw new BadRequestException("File size exceeds maximum allowed size");
    }

    String content_type = file.getContentType();
    if (content_type == null || !allowedTypes.contains(content_type)) {
        throw new BadRequestException("File type not allowed: " + content_type);
    }

    try {
        String extension = getExtension(content_type);
        String fileName = UUID.randomUUID() + extension;
        Path filePath = resolveWithinUploadDir(fileName);
        if (filePath == null) {
            throw new BadRequestException("Invalid file path");
        }

        Files.write(filePath, file.getBytes());

        log.info("File stored: {}", fileName);
        return urlPrefix + fileName;
    } catch (IOException e) {
        throw new InternalServerException("Failed to store file", e);
    }
}
